from pybricks.hubs import PrimeHub
from pybricks.tools import multitask, run_task, wait

from MBC_laser8_obj_Lib import MBC_LASER8

# Set up.
prime_hub = PrimeHub()
laser8 = MBC_LASER8(2, True)

async def main():
    # Connect Laser8 sensor to port B (2) and enable multitasking (true).
    while True:
        await wait(0)
        print(await laser8.ch(1), await laser8.ch(2), await laser8.ch(3), await laser8.ch(4), await laser8.ch(5), await laser8.ch(6), await laser8.ch(7), await laser8.ch(8))
        await wait(50)
    print(await laser8.distances())
    print(await laser8.min_direction(), await laser8.min_distance(), await laser8.max_direction(), await laser8.max_distance())
    print(await laser8.init_status())
    print(await laser8.fault_status())
    # # ════════════════════════════════════════════════════════════════
    # #  【API 函式說明庫】 (可用於主程式的參考)
    # #
    # #  距離單位一律為「公分」0~120；120 代表無目標或超過 120cm。
    # #  方向一律為 -8~+8；0 = 正前方，負值 = CH1 側，正值 = CH8 側。
    # #
    # #  1. 初始化：
    # #     laser8_init_port_multitask(port, multitask)
    # #       - 說明：初始化感測器並指定連接埠。
    # #       - 參數：port 填寫 1~6，分別對應 SPIKE 主機的 A~F 埠。
    # #       - 參數：multitask 填寫 True/False，分別對應 多工任務與非多工任務。
    # #       - ★ multitask=True 時，必須在 run_task(main()) 之前（最外層）呼叫。
    # #
    # #  2. 獨立通道讀取：
    # #     laser8_ch(ch)
    # #       - 說明：讀取指定單一通道的距離。
    # #       - 參數：ch 填寫 1~8，代表第 1~8 號感測器。
    # #       - 回傳：整數 0~120（公分）。
    # #
    # #     laser8_is_ok(ch)
    # #       - 說明：檢查指定通道是否「開機初始化成功，且目前沒有故障」。
    # #       - 回傳：True (正常) / False (初始化失敗、I2C 錯誤或逾時無回應)。
    # #
    # #  3. 整體狀態分析：
    # #     laser8_min_direction()
    # #       - 說明：最近目標所在的方向。
    # #       - 回傳：整數 -7~+7；若周圍都沒有目標，回傳 -8 或 +8（上次目標偏向的那一側）。
    # #
    # #     laser8_min_distance()
    # #       - 說明：最近目標的距離。
    # #       - 回傳：整數 0~120（公分）。
    # #
    # #     laser8_max_direction()
    # #       - 說明：最遠（最空曠）方向。
    # #       - 回傳：整數 -7~+7。
    # #
    # #     laser8_max_distance()
    # #       - 說明：最遠方向的距離。
    # #       - 回傳：整數 0~120（公分）。
    # #
    # #     laser8_distances()
    # #       - 說明：一次取得 8 顆感測器的距離陣列。
    # #       - 回傳：長度為 8 的整數 list，例如 [120, 50, 120, ...]。
    # #
    # #     laser8_init_status()
    # #       - 說明：8 顆感測器開機初始化是否成功。
    # #       - 回傳：長度為 8 的布林 list，例如 [True, True, False, ...]。
    # #
    # #     laser8_fault_status()
    # #       - 說明：8 顆感測器目前是否故障（I2C 錯誤或逾時無回應）。
    # #       - 回傳：長度為 8 的布林 list，True = 故障。
    # #
    # #     laser8_read_all()
    # #       - 說明：一次取得所有解析完畢的綜合狀態字典 (dict)，只讀一次硬體。
    # #
    # #  4. 物件式寫法（圖形化工具的 Setup 區使用）：
    # #     laser8 = MBC_LASER8(port, multitask)，方法名稱去掉 laser8_ 前綴，
    # #     例如 laser8.ch(3)、laser8.min_distance()，詳見檔案最下方說明。
    # # ════════════════════════════════════════════════════════════════


run_task(main())